   110	    public synchronized Reservation checkIn(long reservationId) {
   111	        Reservation reservation = find(reservationId);
   112	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   113	            throw notAllowed(reservation, "check in");
   114	        }
   115	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   116	        store.update(reservation);
   117	        return reservation;
   118	    }
   119	
   120	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   121	    public synchronized ReservationReceipt checkOut(long reservationId) {
